style.css:
@-moz-document url("chrome://newtab/"), url-prefix("https://www.google.com/") {
/* Фон страницы: розовый градиент с вишнёвыми акцентами + ваше изображение */
    body, .theme-default #viewport {
        background-color: #FFC0CB !important; /* Светло-розовый фон по умолчанию */
        background-image: url('https://i.pinimg.com/736x/f7/6a/56/f76a561b7edfe5d2e61f89f082092236.jpg') !important; /* Замените на URL вашего изображения или base64 */
        background-size: cover !important; /* Изображение на весь экран */
        background-position: center !important;
        background-repeat: no-repeat !important;
        color: #C2185B !important; /* Вишнёвый текст для контраста */
    }

    /* Кастомный логотип Google: заменяем стандартный на ваше изображение */
    #logo, .logo, [alt="Google"] {
        background-image: url('https://cdn.freebiesupply.com/images/large/2x/google-logo-black-transparent.png') !important; /* Замените на URL вашего логотипа или base64 */
        background-size: contain !important;
        background-repeat: no-repeat !important;
        width: 272px !important; /* Стандартный размер логотипа Google, скорректируйте под ваше изображение */
        height: 92px !important;
        background-color: transparent !important; /* Убираем фон под логотипом */
    }

    /* Кастомизация поисковой строки и кнопок в вишнёвых/розовых тонах */
    .gstl_0.sbdd_a, .RNNXgb { /* Поисковая строка */
        background-color: #FFC0CB !important;
        border: 1px solid #C2185B !important;
        box-shadow: 0 2px 5px rgba(194, 24, 91, 0.2) !important; /* Вишнёвая тень */
    }

    .gNO89b, .RNmpXc { /* Кнопки "Поиск в Google" и "Мне повезёт!" */
        background-color: #C2185B !important; /* Вишнёвый фон */
        color: #FFFFFF !important; /* Белый текст */
        border: none !important;
    }

    .gNO89b:hover, .RNmpXc:hover {
        background-color: #AD1457 !important; /* Тёмный вишнёвый при наведении */
    }

    /* Дополнительные элементы: ссылки, футер и т.д. */
    a, .fl a {
        color: #C2185B !important; /* Вишнёвые ссылки */
    }

    .fbar, #fbar { /* Футер */
        background-color: #FFC0CB !important;
        color: #C2185B !important;
    }

    /* Для новой вкладки: скрываем/стилизуем стандартные элементы */
    #mv-tiles, .mv-row { /* Плитки быстрого доступа */
        background-color: rgba(255, 192, 203, 0.8) !important; /* Полупрозрачный розовый */
    }

    /* Если фон слишком яркий, добавьте оверлей */
    body::before {
        content: "";
        position: fixed;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background: linear-gradient(to bottom, rgba(255, 192, 203, 0.5), rgba(194, 24, 91, 0.3)) !important; /* Розово-вишнёвый градиент оверлей */
        z-index: -1;
    }
}
